data.query:
query ApplicationConfiguration($where: ApplicationConfigurationWhereInput, $orderBy: [ApplicationConfigurationOrderByInput!], $first: Int, $after: String) {
  applicationConfiguration(
    where: $where
    orderBy: $orderBy
    first: $first
    after: $after
  ) {
    edges {
      node {
        id
        name
        configJson
      }
    }
  }
}

data.transform:
/* $each($appConfig, function($v, $k) {
  $k != "METADATA" ? {
    $k: {
      "id": $k,
      "options": $v.options.{ "id": value, "label": label },
      "method": $v.method,
      "methodLabel": $v.options[value = $v.method].label
    }
  }
}) ~> $merge() */



$merge([$appConfig, $each($omit($appConfig, ["companyInformation", "METADATA"]), function($v, $k) {
  {$k: $merge([$v, {
    "id": $k,
    "options": $v.options.{ "id": value, "label": label },
    "method": $v.method,
    "methodLabel": $v.options[value = $v.method].label
  }])}
}), {
  "companyInformation": $merge([$appConfig.companyInformation, {
    "textAddress": $appConfig.companyInformation.Address1 & ($appConfig.companyInformation.Address2 ? " " & $appConfig.companyInformation.Address2 : "") & ", " & $appConfig.companyInformation.City & ", " & $appConfig.companyInformation.StateProvince & " " & $appConfig.companyInformation.PostalCode,
    "phoneNumber": ($p := $replace($appConfig.companyInformation.Phone, "-", ""); $substring($p, 0, 1) = "+" ? $appConfig.companyInformation.Phone : $replace($p, /(\d{3})(\d{3})(\d{4})/, "($1) $2-$3"))
  }])
}])

